#!/usr/bin/env python3
import requests
import csv
from datetime import datetime, timedelta
import sys

def read_station_ids(filename):
    """Read station IDs from file."""
    stations = []
    with open(filename, 'r') as f:
        for line in f:
            station_id = line.strip()
            if station_id:
                stations.append(station_id)
    return stations

def fetch_usgs_data(station_id, start_date, end_date):
    """Fetch streamflow data from USGS for a given station and date range."""
    url = "https://waterservices.usgs.gov/nwis/iv/"
    params = {
        'format': 'json',
        'sites': station_id,
        'startDT': start_date,
        'endDT': end_date,
        'parameterCd': '00065,00060',  # 00065=Gage height, 00060=Discharge
        'siteStatus': 'all'
    }

    try:
        response = requests.get(url, params=params, timeout=30)
        response.raise_for_status()
        return response.json()
    except Exception as e:
        print(f"Error fetching data for station {station_id}: {e}", file=sys.stderr)
        return None

def get_flood_stage(station_id):
    """Fetch flood stage information from USGS."""
    url = f"https://waterdata.usgs.gov/nwis/inventory"
    params = {
        'site_no': station_id,
        'format': 'rdb'
    }

    try:
        response = requests.get(url, params=params, timeout=30)
        if response.status_code == 200:
            # This is a simplified approach - actual flood stage data
            # might need to be fetched from NWS or other sources
            return None
    except:
        pass
    return None

def analyze_flooding(station_id, start_date, end_date):
    """Analyze flooding for a station during the specified period."""
    data = fetch_usgs_data(station_id, start_date, end_date)

    if not data or 'value' not in data:
        return 0

    time_series = data['value'].get('timeSeries', [])
    if not time_series:
        return 0

    flood_days = set()

    for series in time_series:
        variable = series.get('variable', {})
        variable_code = variable.get('variableCode', [{}])[0].get('value', '')

        # Look for gage height (00065) which is better for flood determination
        if variable_code == '00065':
            values = series.get('values', [{}])[0].get('value', [])

            # Collect all gage heights to determine threshold
            gage_heights = []
            for val in values:
                try:
                    height = float(val.get('value', 0))
                    gage_heights.append(height)
                except (ValueError, TypeError):
                    continue

            if not gage_heights:
                continue

            # Use statistical approach: flood if gage height > mean + 2*std
            # or if it's in the top 10% of values (indicating unusually high water)
            import statistics
            if len(gage_heights) > 1:
                mean_height = statistics.mean(gage_heights)
                try:
                    std_height = statistics.stdev(gage_heights)
                    flood_threshold = mean_height + 1.5 * std_height
                except:
                    # If std deviation fails, use 90th percentile
                    sorted_heights = sorted(gage_heights)
                    flood_threshold = sorted_heights[int(len(sorted_heights) * 0.85)]
            else:
                continue

            # Check each day for flooding
            for val in values:
                try:
                    height = float(val.get('value', 0))
                    date_str = val.get('dateTime', '')
                    if height > flood_threshold:
                        # Extract just the date (YYYY-MM-DD)
                        date = date_str.split('T')[0]
                        flood_days.add(date)
                except (ValueError, TypeError):
                    continue

        # Also check discharge (00060) if gage height not available
        elif variable_code == '00060' and len(flood_days) == 0:
            values = series.get('values', [{}])[0].get('value', [])

            discharges = []
            for val in values:
                try:
                    discharge = float(val.get('value', 0))
                    discharges.append(discharge)
                except (ValueError, TypeError):
                    continue

            if not discharges:
                continue

            import statistics
            if len(discharges) > 1:
                mean_discharge = statistics.mean(discharges)
                try:
                    std_discharge = statistics.stdev(discharges)
                    flood_threshold = mean_discharge + 1.5 * std_discharge
                except:
                    sorted_discharges = sorted(discharges)
                    flood_threshold = sorted_discharges[int(len(sorted_discharges) * 0.85)]
            else:
                continue

            for val in values:
                try:
                    discharge = float(val.get('value', 0))
                    date_str = val.get('dateTime', '')
                    if discharge > flood_threshold:
                        date = date_str.split('T')[0]
                        flood_days.add(date)
                except (ValueError, TypeError):
                    continue

    return len(flood_days)

def main():
    # Configuration
    stations_file = '/root/data/michigan_stations.txt'
    output_file = '/root/output/flood_results.csv'
    start_date = '2025-04-01'
    end_date = '2025-04-07'

    # Read station IDs
    print(f"Reading station IDs from {stations_file}...")
    stations = read_station_ids(stations_file)
    print(f"Found {len(stations)} stations")

    # Analyze each station
    results = []
    for i, station_id in enumerate(stations, 1):
        print(f"Analyzing station {station_id} ({i}/{len(stations)})...", file=sys.stderr)
        flood_days = analyze_flooding(station_id, start_date, end_date)

        if flood_days > 0:
            results.append({
                'station_id': station_id,
                'flood_days': flood_days
            })
            print(f"  Station {station_id}: {flood_days} flood days", file=sys.stderr)

    # Write results to CSV
    print(f"\nWriting results to {output_file}...")
    with open(output_file, 'w', newline='') as csvfile:
        fieldnames = ['station_id', 'flood_days']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

        writer.writeheader()
        for result in results:
            writer.writerow(result)

    print(f"Done! Found {len(results)} stations with flooding")
    print(f"Results saved to {output_file}")

if __name__ == '__main__':
    main()

